#!/bin/sh
set -eu
ROOT_DIR=$(CDPATH= cd -- "$(dirname -- "$0")/../.." && pwd)
DISK_IMAGE="${SECUAGENTOS_DISK:-$ROOT_DIR/.build/vm/secuagentos-x86_64-ubuntu24.04.img}"
SEED_ISO="${SECUAGENTOS_SEED_ISO:-$ROOT_DIR/.build/vm/secuagentos-x86-64-cloud-init.iso}"
# Accept the canonical seed name generated by build.sh; the fallback above is corrected below.
SEED_ISO="$ROOT_DIR/.build/vm/secuagentos-x86_64-cloud-init.iso"

[ -f "$DISK_IMAGE" ] || { echo "VM disk image not found: $DISK_IMAGE" >&2; exit 1; }
[ -f "$SEED_ISO" ] || { echo "cloud-init seed ISO not found: $SEED_ISO" >&2; exit 1; }
command -v qemu-system-x86_64 >/dev/null 2>&1 || { echo "missing required command: qemu-system-x86_64" >&2; exit 1; }

OVMF_CODE="${OVMF_CODE:-}"
OVMF_VARS_TEMPLATE="${OVMF_VARS:-}"
for candidate in /usr/share/OVMF/OVMF_CODE_4M.fd /usr/share/OVMF/OVMF_CODE.fd /usr/share/edk2/ovmf/OVMF_CODE.fd; do
  if [ -z "$OVMF_CODE" ] && [ -f "$candidate" ] && [ -r "$candidate" ]; then OVMF_CODE="$candidate"; fi
done
for candidate in /usr/share/OVMF/OVMF_VARS_4M.fd /usr/share/OVMF/OVMF_VARS.fd /usr/share/edk2/ovmf/OVMF_VARS.fd; do
  if [ -z "$OVMF_VARS_TEMPLATE" ] && [ -f "$candidate" ] && [ -r "$candidate" ]; then OVMF_VARS_TEMPLATE="$candidate"; fi
done
OVMF_MONOLITHIC="${OVMF_MONOLITHIC:-}"
for candidate in /usr/share/qemu/OVMF.fd /usr/share/edk2/ovmf/OVMF.fd; do
  if [ -z "$OVMF_CODE" ] && [ -z "$OVMF_MONOLITHIC" ] && [ -f "$candidate" ] && [ -r "$candidate" ]; then OVMF_MONOLITHIC="$candidate"; fi
done

if [ -n "$OVMF_CODE" ]; then
  echo "Using split OVMF CODE: $OVMF_CODE" >&2
else
  [ -n "$OVMF_MONOLITHIC" ] || { echo "OVMF firmware not found" >&2; exit 1; }
  echo "Using monolithic OVMF: $OVMF_MONOLITHIC" >&2
fi

ACCEL="${SECUAGENTOS_ACCEL:-}"
if [ -z "$ACCEL" ]; then
  if [ -r /dev/kvm ] && [ -w /dev/kvm ]; then ACCEL=kvm; else ACCEL=tcg; fi
fi
echo "QEMU accelerator: $ACCEL" >&2

tmp_dir=""
cleanup() { [ -z "$tmp_dir" ] || rm -rf "$tmp_dir"; }
trap cleanup EXIT INT TERM
FIRMWARE_ARGS=""
if [ -n "$OVMF_CODE" ]; then
  if [ -n "$OVMF_VARS_TEMPLATE" ]; then
    tmp_dir=$(mktemp -d "${TMPDIR:-/tmp}/secuagentos-ovmf.XXXXXX")
    vars_file="$tmp_dir/OVMF_VARS.fd"
    cp "$OVMF_VARS_TEMPLATE" "$vars_file"
    FIRMWARE_ARGS="-drive if=pflash,format=raw,readonly=on,file=$OVMF_CODE -drive if=pflash,format=raw,file=$vars_file"
  else
    FIRMWARE_ARGS="-drive if=pflash,format=raw,readonly=on,file=$OVMF_CODE"
  fi
else
  FIRMWARE_ARGS="-bios $OVMF_MONOLITHIC"
fi

# Ubuntu cloud image is the guest OS. cloud-init seed provides the SecuAgentOS bootstrap service.
# stdout remains the guest serial console; QEMU monitor is disabled to keep CI logs deterministic.
# shellcheck disable=SC2086
exec qemu-system-x86_64 \
  -machine "q35,accel=$ACCEL" \
  -cpu max \
  -m "${SECUAGENTOS_RAM_MB:-4096}" \
  -smp "${SECUAGENTOS_VCPU:-2}" \
  $FIRMWARE_ARGS \
  -drive "if=virtio,format=qcow2,file=$DISK_IMAGE" \
  -drive "if=virtio,media=cdrom,format=raw,file=$SEED_ISO" \
  -boot order=c,menu=off \
  -display none \
  -monitor none \
  -serial stdio \
  -no-reboot
